/**
 * Generates a TEST keypair and the signed license fixtures under
 * `test/fixtures/license/` (plan E1.5.1, OS6.7). Only the public key and the
 * fixtures are written; the private key stays in memory and is discarded, so
 * the tree carries no private key. The production signing key is generated by
 * the key tool in the private repository and never enters this tree; only its
 * public half is baked into `apps/api/src/modules/license/license.constants.ts`.
 *
 * Run: `npx ts-node --transpile-only scripts/license/make-fixture-keypair.ts`
 * Re-running replaces `public.pem` and every fixture together, so a spec that
 * pins a signature byte for byte would be wrong by design; the specs pin outcomes.
 */
import { generateKeyPairSync, sign } from 'node:crypto';
import * as fs from 'node:fs';
import * as path from 'node:path';
// Relative on purpose: plain ts-node runs this and honours no tsconfig paths.
// eslint-disable-next-line @nx/enforce-module-boundaries
import { canonicalJson } from '../../libs/shared/common/src/license/canonical-json';

const OUT = path.resolve(__dirname, '..', '..', 'test', 'fixtures', 'license');
fs.mkdirSync(OUT, { recursive: true });

const { publicKey, privateKey } = generateKeyPairSync('ed25519');
const publicPem = publicKey.export({ type: 'spki', format: 'pem' }).toString();
fs.writeFileSync(path.join(OUT, 'public.pem'), publicPem);

interface Claims {
  id: string;
  licensee: string;
  plan: string;
  storeCap: number;
  domains: string[];
  issuedAt: string;
  expiresAt: string;
}

function licenseFile(claims: Claims, signWith = privateKey): string {
  const signature = sign(null, Buffer.from(canonicalJson(claims), 'utf8'), signWith).toString(
    'base64',
  );
  return JSON.stringify({ claims, signature }, null, 2) + '\n';
}

/** Far enough in the future that the suite does not age into `expiring`. */
const FAR_FUTURE = '2099-01-01T00:00:00.000Z';
const base: Claims = {
  id: 'lic-fixture-0001',
  licensee: 'Fixture Agency',
  plan: 'studio',
  storeCap: 3,
  // Every store-config fixture's domains plus the local development
  // origins, so the e2e API boots under any `STORE_CONFIG_FIXTURE`
  // (demo, maghreb-ltr, gulf-rtl) and a demo-config box also passes.
  domains: [
    'demo.example',
    'admin.demo.example',
    'api.demo.example',
    'atlas.example',
    'admin.atlas.example',
    'api.atlas.example',
    'marsa.example',
    'admin.marsa.example',
    'api.marsa.example',
    'localhost',
    '127.0.0.1',
  ],
  issuedAt: '2026-09-03T00:00:00.000Z',
  expiresAt: FAR_FUTURE,
};

fs.writeFileSync(path.join(OUT, 'valid.license.json'), licenseFile(base));
fs.writeFileSync(
  path.join(OUT, 'expired.license.json'),
  licenseFile({ ...base, id: 'lic-fixture-expired', expiresAt: '2026-01-01T00:00:00.000Z' }),
);
fs.writeFileSync(
  path.join(OUT, 'wrong-domain.license.json'),
  licenseFile({ ...base, id: 'lic-fixture-domain', domains: ['other.example'] }),
);
// Signed by a key the engine does not trust.
const stranger = generateKeyPairSync('ed25519').privateKey;
fs.writeFileSync(
  path.join(OUT, 'untrusted.license.json'),
  licenseFile({ ...base, id: 'lic-fixture-untrusted' }, stranger),
);
// A valid signature over claims that were then edited.
const tampered = JSON.parse(licenseFile(base)) as { claims: Claims; signature: string };
tampered.claims.storeCap = 999;
fs.writeFileSync(path.join(OUT, 'tampered.license.json'), JSON.stringify(tampered, null, 2) + '\n');

console.log(`wrote the public key and 5 license fixtures to ${OUT}`);
